import {
  FolderSortOptions,
  FolderSortPreview,
  FolderSortPreviewItem,
} from '../types';
import {
  getFolderChildren,
  moveBookmark,
  deleteBookmark,
  getBookmarkTree,
} from './bookmarkManager';
import { createBookmarkSnapshot } from './backupService';

/**
 * Matches only the placeholder URL and title formats generated by old EdgeMark
 * versions. Decorative titles alone must never identify bookmarks or folders.
 */
export function isLegacyDividerBookmark(node: { url?: string; title?: string }): boolean {
  return node.url === 'about:blank#separator' && (
    node.title === '────────────────────' || /^─── .+ ───$/.test(node.title || '')
  );
}

/**
 * Normalizes URL to its domain name
 */
export function getDomainFromUrl(rawUrl: string): string {
  try {
    const parsed = new URL(rawUrl);
    return parsed.hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return 'other';
  }
}

const KNOWN_BRANDS: Record<string, string> = {
  'github.com': 'GitHub',
  'azure.com': 'Azure',
  'portal.azure.com': 'Azure',
  'learn.microsoft.com': 'Microsoft Learn',
  'microsoft.com': 'Microsoft',
  'aws.amazon.com': 'AWS',
  'amazon.com': 'Amazon',
  'google.com': 'Google',
  'reddit.com': 'Reddit',
  'linear.app': 'Linear',
  'notion.so': 'Notion',
  'jira.com': 'Jira',
  'atlassian.com': 'Atlassian',
  'servicenow.com': 'ServiceNow',
  'service-now.com': 'ServiceNow',
  'skf.net': 'SKF Internal',
  'skf.com': 'SKF Portal',
  'youtube.com': 'YouTube',
  'docker.com': 'Docker',
  'kubernetes.io': 'Kubernetes',
  'openai.com': 'OpenAI',
  'chatgpt.com': 'ChatGPT',
  'stackoverflow.com': 'Stack Overflow',
  'wikipedia.org': 'Wikipedia',
};

/**
 * Formats a clean display name for a domain
 */
export function getDomainDisplayName(domain: string): string {
  if (!domain || domain === 'other') return 'General Links';

  const clean = domain.toLowerCase().replace(/^(www\.|portal\.|login\.|app\.)+/, '');
  if (KNOWN_BRANDS[clean]) return KNOWN_BRANDS[clean];
  if (KNOWN_BRANDS[domain.toLowerCase()]) return KNOWN_BRANDS[domain.toLowerCase()];

  // Check homelab / local network (.lan, .local, .home)
  if (clean.endsWith('.lan') || clean.endsWith('.local') || clean.endsWith('.home')) {
    const host = clean.split('.')[0];
    return `${host.charAt(0).toUpperCase() + host.slice(1)} (Homelab)`;
  }

  // Capitalize main domain
  const parts = clean.split('.');
  if (parts.length >= 2) {
    const main = parts[0];
    return main.charAt(0).toUpperCase() + main.slice(1);
  }

  return clean;
}

/**
 * Sorts bookmark items by the specified criteria
 */
export function sortBookmarkList<T extends { title?: string; url?: string; dateAdded?: number }>(
  items: T[],
  options: FolderSortOptions
): T[] {
  const sorted = [...items];

  sorted.sort((a, b) => {
    const titleA = (a.title || '').trim().toLowerCase();
    const titleB = (b.title || '').trim().toLowerCase();

    switch (options.criteria) {
      case 'domain-alpha': {
        const domA = getDomainFromUrl(a.url || '');
        const domB = getDomainFromUrl(b.url || '');
        const nameA = getDomainDisplayName(domA);
        const nameB = getDomainDisplayName(domB);
        const domCmp = nameA.localeCompare(nameB);
        if (domCmp !== 0) return domCmp;
        return titleA.localeCompare(titleB);
      }
      case 'alpha-asc':
        return titleA.localeCompare(titleB);
      case 'alpha-desc':
        return titleB.localeCompare(titleA);
      case 'date-desc':
        return (b.dateAdded || 0) - (a.dateAdded || 0);
      case 'date-asc':
        return (a.dateAdded || 0) - (b.dateAdded || 0);
      default:
        return titleA.localeCompare(titleB);
    }
  });

  return sorted;
}

/**
 * Previews bookmark order and legacy placeholder cleanup for a given folder
 */
export async function previewFolderSort(
  folderId: string,
  folderTitle: string,
  folderPath: string,
  options: FolderSortOptions
): Promise<FolderSortPreview> {
  const children = await getFolderChildren(folderId);

  // Filter out existing divider bookmarks
  const actualBookmarks = children.filter((c) => Boolean(c.url) && !isLegacyDividerBookmark(c));
  const sorted = sortBookmarkList(actualBookmarks, options);
  const planned: FolderSortPreviewItem[] = sorted.map((bookmark) => ({
    id: bookmark.id,
    title: bookmark.title || bookmark.url || 'Untitled',
    url: bookmark.url,
    domain: getDomainFromUrl(bookmark.url || ''),
  }));

  const uniqueDomains = new Set(actualBookmarks.map((b) => getDomainFromUrl(b.url || '')));

  return {
    folderId,
    folderTitle,
    folderPath,
    itemCount: actualBookmarks.length,
    domainCount: uniqueDomains.size,
    dividersToRemove: children.filter(isLegacyDividerBookmark).length,
    items: planned,
  };
}

/**
 * Sorts a folder without creating bookmarks. Removes old EdgeMark placeholders
 * after backing up the library, preserving real bookmarks and every subfolder.
 */
export async function sortFolder(
  folderId: string,
  options: FolderSortOptions = { criteria: 'domain-alpha', sortSubfoldersFirst: true },
  // Reorganization already saved its snapshot before moving any bookmarks.
  backupAlreadySaved = false
): Promise<{ modifiedCount: number; dividersRemoved: number }> {
  if (!backupAlreadySaved) await createBookmarkSnapshot();
  return applyFolderSort(folderId, options);
}

// Bulk sorting already takes one library snapshot before calling this helper.
async function applyFolderSort(
  folderId: string,
  options: FolderSortOptions
): Promise<{ modifiedCount: number; dividersRemoved: number }> {
  const children = await getFolderChildren(folderId);
  const subfolders = children.filter((child) => !child.url);
  const existingDividers = children.filter(isLegacyDividerBookmark);
  const bookmarks = children.filter((child) => Boolean(child.url) && !isLegacyDividerBookmark(child));

  for (const divider of existingDividers) {
    await deleteBookmark(divider.id);
  }

  const sortedBookmarks = sortBookmarkList(bookmarks, options);
  const sortSubfoldersFirst = options.sortSubfoldersFirst !== false;
  let currentIndex = sortSubfoldersFirst ? subfolders.length : 0;

  if (sortSubfoldersFirst) {
    for (let i = 0; i < subfolders.length; i++) {
      await moveBookmark(subfolders[i].id, folderId, i);
    }
  }

  for (const bookmark of sortedBookmarks) {
    await moveBookmark(bookmark.id, folderId, currentIndex++);
  }

  return {
    modifiedCount: bookmarks.length,
    dividersRemoved: existingDividers.length,
  };
}

/**
 * Recursively retrieves all folder IDs under a root node
 */
function collectFolderNodes(
  node: chrome.bookmarks.BookmarkTreeNode | any,
  currentPath = ''
): { id: string; title: string; path: string; childBookmarkCount: number; legacyDividerCount: number }[] {
  const folders: { id: string; title: string; path: string; childBookmarkCount: number; legacyDividerCount: number }[] = [];
  const nextPath = node.title ? (currentPath ? `${currentPath} / ${node.title}` : node.title) : currentPath;

  if (!node.url && node.id) {
    const childBookmarks = (node.children || []).filter((c: any) => Boolean(c.url) && !isLegacyDividerBookmark(c));
    folders.push({
      id: node.id,
      title: node.title || 'Folder',
      path: nextPath || 'Favorites bar',
      childBookmarkCount: childBookmarks.length,
      legacyDividerCount: (node.children || []).filter(isLegacyDividerBookmark).length,
    });
  }

  if (node.children) {
    for (const child of node.children) {
      if (!child.url) {
        folders.push(...collectFolderNodes(child, nextPath));
      }
    }
  }

  return folders;
}

/**
 * Sorts all folders in the bookmark tree matching the options
 */
export async function sortAllFolders(
  options: FolderSortOptions,
  onProgress?: (completed: number, total: number, currentFolder: string) => void
): Promise<{ foldersSorted: number; bookmarksSorted: number; dividersRemoved: number; failedFolders: number }> {
  // Take safety backup snapshot first
  await createBookmarkSnapshot();

  const tree = await getBookmarkTree();
  let allFolders: { id: string; title: string; path: string; childBookmarkCount: number; legacyDividerCount: number }[] = [];

  for (const root of tree) {
    allFolders.push(...collectFolderNodes(root));
  }

  // Include marker-only and single-bookmark folders needing legacy cleanup.
  const candidateFolders = allFolders.filter((f) => f.childBookmarkCount >= 2 || f.legacyDividerCount > 0);

  let foldersSorted = 0;
  let bookmarksSorted = 0;
  let dividersRemoved = 0;
  let failedFolders = 0;

  for (let i = 0; i < candidateFolders.length; i++) {
    const f = candidateFolders[i];
    if (onProgress) {
      onProgress(i + 1, candidateFolders.length, f.path);
    }

    try {
      const res = await applyFolderSort(f.id, options);
      if (res.modifiedCount > 0 || res.dividersRemoved > 0) {
        foldersSorted++;
        bookmarksSorted += res.modifiedCount;
        dividersRemoved += res.dividersRemoved;
      }
    } catch (err) {
      failedFolders++;
      console.warn(`Failed to sort folder "${f.path}":`, err);
    }
  }

  return { foldersSorted, bookmarksSorted, dividersRemoved, failedFolders };
}
